<?php get_header();while(have_posts()):the_post(); ?><main id="primary"><?php rzz_intro(get_the_title(),get_the_excerpt()); ?><section class="section light"><div class="container service-layout"><article class="service-main"><p class="eyebrow">Overview</p><div class="prose"><?php the_content(); ?></div><h2 class="small-heading">Our services include</h2><ul class="check-list"><?php foreach(rzz_lines(rzz_meta('services')) as $line)echo '<li>'.esc_html($line).'</li>'; ?></ul><div class="service-callout pattern"><?php echo rzz_icon(get_post_field('post_name',get_the_ID())); ?><div><h3>Legal support shaped around your priorities.</h3><a class="text-link" href="#contact-form">Discuss your matter <?php echo rzz_arrow(); ?></a></div></div></article><aside class="service-aside"><p class="eyebrow">Why RZZ LAW</p><h2>A considered approach.</h2><p><?php echo esc_html(rzz_meta('approach')?:'We take time to understand the circumstances of your matter, explain the available options and agree practical next steps. You receive direct communication and focused legal support throughout.'); ?></p><ul class="approach-list"><li><strong>Business-oriented</strong><p>Advice aligned with your objectives.</p></li><li><strong>Carefully prepared</strong><p>Attention to documentation, risk and process.</p></li><li><strong>Personal commitment</strong><p>A clear point of contact for your matter.</p></li></ul></aside></div><div class="container related pattern"><p class="eyebrow">Related expertise</p><div class="related-grid"><?php $slugs=rzz_lines(rzz_meta('related'));$query=['post_type'=>'expertise','numberposts'=>2,'exclude'=>[get_the_ID()],'orderby'=>'menu_order','order'=>'ASC'];if($slugs)$query['post_name__in']=$slugs;foreach(get_posts($query) as $item)echo '<a class="related-card has-photo" href="'.esc_url(get_permalink($item)).'"><img class="related-photo" src="'.esc_url(rzz_related_image($item,800)).'" '.rzz_photo_attributes(rzz_related_image_details($item)).' width="800" height="533" loading="lazy" decoding="async"><h3>'.esc_html($item->post_title).'</h3>'.rzz_arrow().'</a>'; ?></div></div></section><?php get_template_part('template-parts/principles-band'); get_template_part('template-parts/contact'); ?></main><?php endwhile;get_footer(); ?>